export function memory(run,index,stats){
 if(index===4&&run.choices[3]===1)return 'Na decisão anterior, você combinou uma retomada com a escola. Agora existe um contato a quem contar essa nova dificuldade.';
 if(index===4&&run.choices[3]===2)return 'A madrugada de estudo deixou uma marca no seu fôlego. A dificuldade de acesso chega em uma semana que já está pesada.';
 if(index===8&&run.choices[6]===0)return 'Você lembra da devolutiva que ajudou a nomear uma dificuldade. Essa experiência torna possível imaginar uma nova conversa.';
 if(index===10&&stats.energy<25)return 'As escolhas anteriores deixaram pouco fôlego. O esforço desta etapa chega a um corpo que precisa de descanso.';
 if(index===10&&stats.network>=65)return 'A rede construída ao longo do percurso está mais forte. Você sabe que pode conversar sobre as dúvidas desta etapa.';
 return '';
}
export function choiceOrder(index,character){const offset=(index+['ana','marcos','celia'].indexOf(character))%3;return [0,1,2].map(i=>(i+offset)%3);}
